  App.view_inventoryLocations=async function(){await reloadBase();setContent('<div class="sg75-page"><div class="sg75-toolbar"><div><small>KONFIGURIM</small><h2>Lokacionet e Magazinës</h2></div><div>'+btn('＋ Shto Lokacion','App.sg75StandaloneQuick(\'location\')','primary')+'</div></div><div class="sg75-filter"><input type="search" placeholder="Kërko kod, emër, barkod..." oninput="App.sg75FilterTable(this.value,\'sg75-locations-table\')"></div><div class="sg75-table-wrap"><table id="sg75-locations-table"><thead><tr><th>Kodi</th><th>Lokacioni</th><th>Lloji</th><th>Magazina</th><th>Furnitori</th><th>Gjendja</th></tr></thead><tbody>'+S.locations.map(function(x){return'<tr><td><strong>'+esc(x.code)+'</strong></td><td>'+esc(x.completeName||x.name)+'</td><td>'+esc(x.locationType)+'</td><td>'+esc(x.warehouseName||'—')+'</td><td>'+esc(x.supplierName||'—')+'</td><td class="right">'+fmt(x.onHand)+'</td></tr>';}).join('')+'</tbody></table></div></div>','Lokacionet');};
  App.sg75StandaloneQuick=function(kind){S.searchFields['sg75-standalone']={id:'sg75-standalone',items:[],warehouseId:(warehouses()[0]||{}).id,onChange:function(){App.navigate(kind==='location'?'inventoryLocations':kind==='lot'?'inventoryLots':'inventoryDashboard');}};quickCreate(kind,'sg75-standalone');};
  App.view_inventoryLots=async function(){var rows=await request('/api/inventory/reports/lots');setContent('<div class="sg75-page"><div class="sg75-toolbar"><div><small>GJURMUESHMËRI</small><h2>Lotet në Inventar</h2></div><div>'+btn('＋ Shto Lot','App.sg75StandaloneQuick(\'lot\')','primary')+'</div></div><div class="sg75-filter"><input type="search" placeholder="Kërko lot, artikull, furnitor..." oninput="App.sg75FilterTable(this.value,\'sg75-lots-table\')"></div><div class="sg75-table-wrap"><table id="sg75-lots-table"><thead><tr><th>Loti</th><th>Artikulli</th><th>Furnitori</th><th>Magazina</th><th>Cilësia</th><th>Gjendja</th><th>Rezervuar</th><th>Kosto</th></tr></thead><tbody>'+rows.map(function(x){return'<tr onclick="App.sg72OpenLotDocument&&App.sg72OpenLotDocument(\''+x.id+'\')"><td><a>'+esc(x.lotNumber)+'</a></td><td>'+esc((x.productCode?x.productCode+' — ':'')+x.productName)+'</td><td>'+esc((x.supplierCode?x.supplierCode+' — ':'')+(x.supplierName||'—'))+'</td><td>'+esc(x.warehouseName)+'</td><td>'+esc(x.qualityStatus)+'</td><td class="right">'+fmt(x.quantityAvailable)+'</td><td class="right">'+fmt(x.quantityReserved)+'</td><td class="right">'+fmt(x.unitCost,2)+'</td></tr>';}).join('')+'</tbody></table></div></div>','Lotet');};

  App.view_inventoryAdjustments=async function(){await reloadBase();setContent('<div class="sg75-page"><div class="sg75-toolbar"><div><small>INVENTARI FIZIK</small><h2>Rregullime Inventari</h2></div><div>'+btn('＋ Inventar i Ri','App.sg75NewCount()','primary')+'</div></div><div class="sg75-table-wrap"><table><thead><tr><th>Dokumenti</th><th>Data</th><th>Magazina</th><th>Lokacioni</th><th>Rreshta</th><th>Diferenca</th><th>Statusi</th></tr></thead><tbody>'+S.counts.map(function(x){return'<tr><td><strong>'+esc(x.countNo)+'</strong></td><td>'+esc(x.countDate)+'</td><td>'+esc(x.warehouseName)+'</td><td>'+esc(x.locationName)+'</td><td>'+esc(x.lineCount)+'</td><td class="right">'+fmt(x.totalDifference)+'</td><td>'+statusBadge(x.state)+'</td></tr>';}).join('')+'</tbody></table></div></div>','Rregullime Inventari');};
  App.sg75NewCount=function(){var warehouse=warehouses()[0]||{};S.countDraft={warehouseId:warehouse.id||'',locationId:'',date:today(),rows:[{productId:'',lotId:'',countedQuantity:0,unitCost:0}]};renderCount();};
  function renderCount(){var d=S.countDraft,locs=S.locations.filter(function(x){return!d.warehouseId||x.warehouseId===d.warehouseId;});var body='<div class="sg75-form"><div class="sg75-form-grid"><label>Magazina'+searchControl({id:'sg75-count-wh',items:warehouses(),selectedId:d.warehouseId,placeholder:'Kërko magazinën...',onChange:function(row){d.warehouseId=row?.id||'';d.locationId='';renderCount();}})+'</label><label>Lokacioni *'+searchControl({id:'sg75-count-loc',items:locs,selectedId:d.locationId,placeholder:'Kërko lokacionin...',labelFn:function(x){return x.code+' — '+(x.completeName||x.name);},createKind:'location',warehouseId:d.warehouseId,onChange:function(row){d.locationId=row?.id||'';}})+'</label><label>Data<input id="sg75-count-date" type="date" value="'+d.date+'"></label></div><section class="sg75-lines"><header><h3>Numërimi fizik</h3>'+btn('＋ Rresht','App.sg75CountAdd()')+'</header><div id="sg75-count-lines"></div></section></div>';App.modal('Inventar Fizik i Ri',body,btn('Anulo','App.closeModal()')+btn('Ruaj Draft','App.sg75CountSave()','primary'));renderCountLines();bindSearches(document.getElementById('modal-box')||document);}
  App.sg75CountAdd=function(){S.countDraft.rows.push({productId:'',lotId:'',countedQuantity:0,unitCost:0});renderCountLines();};App.sg75CountNumber=function(i,k,v){S.countDraft.rows[i][k]=v;};
  function renderCountLines(){var target=document.getElementById('sg75-count-lines');if(!target)return;target.innerHTML='<div class="sg75-table-wrap"><table><thead><tr><th>Artikulli</th><th>Loti</th><th>Gjendja në sistem</th><th>Numërimi real</th><th>Kosto</th></tr></thead><tbody>'+S.countDraft.rows.map(function(row,i){var lotRows=lots().filter(function(x){return!row.productId||x.productId===row.productId;}),quant=S.quants.find(function(q){return q.locationId===S.countDraft.locationId&&q.productId===row.productId&&String(q.lotId||'')===String(row.lotId||'');});return'<tr><td>'+searchControl({id:'sg75-c-product-'+i,items:products(),selectedId:row.productId,placeholder:'Kërko artikullin...',createKind:'product',onChange:function(x){row.productId=x?.id||'';row.unitCost=num(x?.purchasePrice||x?.purchase_price);renderCountLines();}})+'</td><td>'+searchControl({id:'sg75-c-lot-'+i,items:lotRows,selectedId:row.lotId,placeholder:'Kërko lotin...',createKind:'lot',warehouseId:S.countDraft.warehouseId,productId:row.productId,onChange:function(x){row.lotId=x?.id||'';renderCountLines();}})+'</td><td class="right">'+fmt(quant?.onHand||0)+'</td><td><input type="number" inputmode="decimal" value="'+attr(row.countedQuantity)+'" oninput="App.sg75CountNumber('+i+',\'countedQuantity\',this.value)"></td><td><input type="number" inputmode="decimal" value="'+attr(row.unitCost)+'" oninput="App.sg75CountNumber('+i+',\'unitCost\',this.value)"></td></tr>';}).join('')+'</tbody></table></div>';bindSearches(target);}
  App.sg75CountSave=async function(){try{var d=S.countDraft,lines=d.rows.filter(function(x){return x.productId;}).map(function(x){return{productId:x.productId,lotId:x.lotId||null,countedQuantity:num(x.countedQuantity),unitCost:num(x.unitCost)};});if(!d.locationId)throw new Error('Zgjidhni lokacionin.');if(!lines.length)throw new Error('Shtoni artikujt e numëruar.');await request('/api/inventory/counts',{method:'POST',body:{companyId:companyId(),warehouseId:d.warehouseId,locationId:d.locationId,countDate:value('sg75-count-date'),notes:'',lines:lines}});App.closeModal();App.toast('Inventari u ruajt Draft.');App.navigate('inventoryAdjustments');}catch(error){errorToast(error);}};

  App.view_inventoryReordering=async function(){await reloadBase();setContent('<div class="sg75-page"><div class="sg75-toolbar"><div><small>FURNIZIM AUTOMATIK</small><h2>Rregullat e Furnizimit</h2></div><div>'+btn('＋ Shto Rregull','App.sg75NewRule()','primary')+'</div></div><div class="sg75-table-wrap"><table><thead><tr><th>Artikulli</th><th>Magazina</th><th>Lokacioni</th><th>Gjendja e lirë</th><th>Minimumi</th><th>Maksimumi</th><th>Porosia</th><th>Statusi</th></tr></thead><tbody>'+S.rules.map(function(x){var low=num(x.availableQuantity)<num(x.minQuantity);return'<tr><td>'+esc((x.productCode?x.productCode+' — ':'')+x.productName)+'</td><td>'+esc(x.warehouseName)+'</td><td>'+esc(x.locationName)+'</td><td class="right '+(low?'sg75-low':'')+'">'+fmt(x.availableQuantity)+'</td><td class="right">'+fmt(x.minQuantity)+'</td><td class="right">'+fmt(x.maxQuantity)+'</td><td class="right">'+fmt(x.reorderQuantity)+'</td><td>'+(low?'<span class="sg75-status ready">Duhet furnizuar</span>':'<span class="sg75-status done">Në rregull</span>')+'</td></tr>';}).join('')+'</tbody></table></div></div>','Rregullat e Furnizimit');};
  App.sg75NewRule=function(){var wh=warehouses()[0]||{};var body='<div class="sg75-form-grid"><label>Magazina'+searchControl({id:'sg75-r-wh',items:warehouses(),selectedId:wh.id||'',placeholder:'Kërko magazinën...'})+'</label><label>Lokacioni'+searchControl({id:'sg75-r-loc',items:S.locations,selectedId:'',placeholder:'Kërko lokacionin...',createKind:'location',warehouseId:wh.id})+'</label><label>Artikulli'+searchControl({id:'sg75-r-product',items:products(),selectedId:'',placeholder:'Kërko artikullin...',createKind:'product'})+'</label><label>Minimumi<input id="sg75-r-min" type="number" inputmode="decimal" value="0"></label><label>Maksimumi<input id="sg75-r-max" type="number" inputmode="decimal" value="0"></label><label>Sasia për porosi<input id="sg75-r-qty" type="number" inputmode="decimal" value="0"></label></div>';App.modal('Rregull Furnizimi',body,btn('Anulo','App.closeModal()')+btn('Ruaj','App.sg75SaveRule()','primary'));bindSearches(document.getElementById('modal-box')||document);};
  App.sg75SaveRule=async function(){try{await request('/api/inventory/reordering-rules',{method:'POST',body:{companyId:companyId(),warehouseId:value('sg75-r-wh'),locationId:value('sg75-r-loc'),productId:value('sg75-r-product'),minQuantity:num(value('sg75-r-min')),maxQuantity:num(value('sg75-r-max')),reorderQuantity:num(value('sg75-r-qty')),active:true}});App.closeModal();App.navigate('inventoryReordering');}catch(error){errorToast(error);}};

  var REPORTS={stock:{label:'Stoku',endpoint:'/api/inventory/reports/stock'},locations:{label:'Lokacionet',endpoint:'/api/inventory/reports/locations'},lots:{label:'Lotet',endpoint:'/api/inventory/reports/lots'},moves:{label:'Historiku i Lëvizjeve',endpoint:'/api/inventory/reports/moves'},valuation:{label:'Vlerësimi i Stokut',endpoint:'/api/inventory/reports/valuation'},atDate:{label:'Stoku në Datë',endpoint:'/api/inventory/reports/at-date'},slow:{label:'Stoku pa Lëvizje',endpoint:'/api/inventory/reports/slow-stock'},discrepancies:{label:'Diferencat e Inventarit',endpoint:'/api/inventory/reports/discrepancies'}};
  App.view_inventoryReports=function(){return App.sg75OpenReport('stock');};
  App.sg75OpenReport=async function(type){try{S.reportType=type;var def=REPORTS[type]||REPORTS.stock,path=def.endpoint;if(type==='atDate')path+='?date='+encodeURIComponent(value('sg75-report-date')||today());if(type==='slow')path+='?days='+encodeURIComponent(value('sg75-report-days')||90);S.reportRows=await request(path);renderReport();}catch(error){errorToast(error);}};
  function humanKey(key){return String(key).replace(/([A-Z])/g,' $1').replace(/^./,function(x){return x.toUpperCase();}).replace('Id','ID');}
  function renderReport(){var def=REPORTS[S.reportType],keys=S.reportRows.length?Object.keys(S.reportRows[0]).filter(function(k){return!['id','tenantId','companyId','warehouseId','productId','lotId','transferId','createdBy'].includes(k);}):[];setContent('<div class="sg75-page"><div class="sg75-toolbar"><div><small>RAPORTET INVENTORY</small><h2>'+esc(def.label)+'</h2></div><div>'+btn('Print','App.sg75PrintReport()')+btn('PDF','App.sg75PrintReport()')+btn('Excel .xlsx','App.sg75ExcelReport()','primary')+'</div></div><div class="sg75-report-tabs">'+Object.keys(REPORTS).map(function(key){return'<button type="button" class="'+(key===S.reportType?'active':'')+'" onclick="App.sg75OpenReport(\''+key+'\')">'+esc(REPORTS[key].label)+'</button>';}).join('')+'</div><div class="sg75-report-options">'+(S.reportType==='atDate'?'<label>Data<input id="sg75-report-date" type="date" value="'+today()+'" onchange="App.sg75OpenReport(\'atDate\')"></label>':'')+(S.reportType==='slow'?'<label>Pa lëvizje prej<input id="sg75-report-days" type="number" value="90" onchange="App.sg75OpenReport(\'slow\')"> ditësh</label>':'')+'<input type="search" placeholder="Kërko në raport..." oninput="App.sg75FilterTable(this.value,\'sg75-report-table\')"></div><div class="sg75-table-wrap"><table id="sg75-report-table"><thead><tr>'+keys.map(function(k){return'<th>'+esc(humanKey(k))+'</th>';}).join('')+'</tr></thead><tbody>'+S.reportRows.map(function(row){return'<tr>'+keys.map(function(k){var v=row[k];if(typeof v==='number'||(/^[-+]?\d+(\.\d+)?$/.test(String(v||''))&&/quantity|value|cost|reserved|available|difference|days|onHand/i.test(k)))return'<td class="right">'+fmt(v,2)+'</td>';return'<td>'+esc(Array.isArray(v)?JSON.stringify(v):v==null?'':v)+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div><div class="sg75-report-foot">Rreshta: <strong>'+S.reportRows.length+'</strong></div></div>',def.label);}
  function printable(title,rows){var keys=rows.length?Object.keys(rows[0]).filter(function(k){return!['id','tenantId','companyId','warehouseId','productId','lotId','transferId','createdBy'].includes(k);}):[];return'<!doctype html><html><head><meta charset="utf-8"><title>'+esc(title)+'</title><style>body{font-family:Arial;padding:20px}table{border-collapse:collapse;width:100%;font-size:10px}th,td{border:1px solid #aaa;padding:5px;text-align:left}th{background:#eee}h2{margin:0 0 15px}@media print{button{display:none}}</style></head><body><h2>'+esc(title)+'</h2><button onclick="print()">Print / PDF</button><table><thead><tr>'+keys.map(function(k){return'<th>'+esc(humanKey(k))+'</th>';}).join('')+'</tr></thead><tbody>'+rows.map(function(r){return'<tr>'+keys.map(function(k){return'<td>'+esc(r[k]==null?'':Array.isArray(r[k])?JSON.stringify(r[k]):r[k])+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></body></html>';}
  App.sg75PrintReport=function(){var win=window.open('','_blank');win.document.write(printable(REPORTS[S.reportType].label,S.reportRows));win.document.close();win.focus();};
  App.sg75ExcelReport=function(){if(!global.XLSX)return App.toast('Biblioteka Excel .xlsx nuk është ngarkuar në këtë pajisje.','error');var ws=XLSX.utils.json_to_sheet(S.reportRows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Raport');XLSX.writeFile(wb,'Inventory_'+S.reportType+'_'+today()+'.xlsx');};
  App.sg75PrintCurrent=function(){var current=App._sg75Current||{title:'Dokument',rows:[]},win=window.open('','_blank');win.document.write(printable(current.title,current.rows));win.document.close();win.focus();};
  App.sg75ExportCurrent=function(){if(!global.XLSX)return App.toast('Biblioteka Excel .xlsx nuk është ngarkuar.','error');var current=App._sg75Current||{title:'Dokument',rows:[]},ws=XLSX.utils.json_to_sheet(current.rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Dokument');XLSX.writeFile(wb,current.title+'.xlsx');};

  function addQuickButtonsToLegacy(root){Array.prototype.slice.call((root||document).querySelectorAll('.sg73-combo')).forEach(function(combo){if(combo.dataset.sg75Add==='1')return;var select=combo.previousElementSibling;if(!select||select.tagName!=='SELECT')return;var id=select.id||'',kind='';if(/center|machine|makineri/i.test(id+' '+(select.closest('label,div')||{}).textContent))kind='workCenter';else if(/location|lokacion|raft/i.test(id+' '+(select.closest('label,div')||{}).textContent))kind='location';else if(/product|artikull/i.test(id+' '+(select.closest('label,div')||{}).textContent))kind='product';else if(/supplier|furnitor/i.test(id+' '+(select.closest('label,div')||{}).textContent))kind='supplier';else if(/lot/i.test(id+' '+(select.closest('label,div')||{}).textContent))kind='lot';if(!kind)return;combo.dataset.sg75Add='1';combo.classList.add('sg75-legacy-combo');var add=document.createElement('button');add.type='button';add.className='sg75-add';add.textContent='＋ Shto';add.addEventListener('click',function(){S.searchFields['legacy-'+id]={id:'legacy-'+id,items:[],warehouseId:value('sg75-warehouse')||((warehouses()[0]||{}).id||''),processId:(App.SGPhase74&&App.SGPhase74.draft||{}).processId,onChange:function(row){select.value=row.id;select.dispatchEvent(new Event('change',{bubbles:true}));var input=combo.querySelector('input');if(input)input.value=searchLabelDefault(row);}};quickCreate(kind,'legacy-'+id);});combo.appendChild(add);});}
  var baseModal=App.modal;if(typeof baseModal==='function'){App.modal=function(){var result=baseModal.apply(this,arguments);setTimeout(function(){bindSearches(document);addQuickButtonsToLegacy(document);},0);return result;};}

